	// Load settings once for remote resolution and push_sessions check.
	// Spanned because checkpoint-remote resolution can perform a one-time
	// network fetch of the metadata branch (fetchMetadataBranchIfMissing),
	// which is otherwise invisible in the pre-push trace.
	resolveCtx, resolveSpan := perf.Start(ctx, "resolve_push_settings")
	ps := resolvePushSettings(resolveCtx, remote)
	resolveSpan.End()

	if ps.pushDisabled {
		return nil
	}

	refs := checkpoint.ResolveCommittedRefs(ctx)

	refreshMirrorBeforePush(ctx, refs)

	// Thread the span's context into the push so the network push and any
	// fetch+rebase recovery nest beneath it as child steps in the perf trace.
	pushCtx, pushCheckpointsSpan := perf.Start(ctx, "push_checkpoint_refs")
	defer pushCheckpointsSpan.End()
	for _, ref := range refs.Push {
		if err := pushRefIfNeeded(pushCtx, ps.pushTarget(), ref); err != nil {
			pushCheckpointsSpan.RecordError(err)
			return err
		}
	}
	return nil
}

// refreshMirrorBeforePush advances the mirror to the primary tip before
// pushing. Best-effort: failures are logged, never blocking the push.
func refreshMirrorBeforePush(ctx context.Context, refs checkpoint.CommittedRefs) {
	if !refs.HasMirror() {
		return
	}
	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Debug(ctx, "pre-push mirror refresh skipped: open repository failed",
			slog.String("error", err.Error()))
		return
	}
	defer repo.Close()
	mirrorCommittedMetadataRefBestEffort(ctx, repo, refs)
}
package strategy

import (
	"context"
	"fmt"
	"log/slog"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"

	"github.com/go-git/go-git/v6/plumbing"
)

// checkpointRemoteFetchTimeout is the timeout for fetching branches from the checkpoint URL.
const checkpointRemoteFetchTimeout = 30 * time.Second

// pushSettings holds the resolved push configuration from a single settings load.
type pushSettings struct {
	// remote is the git remote name to use for pushing (the user's push remote).
	remote string
	// checkpointURL is the derived URL for pushing checkpoint branches.
	// When set, checkpoint/trails branches are pushed directly to this URL
	// instead of the remote name. Empty means use the remote name.
	checkpointURL string
	// pushDisabled is true if push_sessions is explicitly set to false.
	pushDisabled bool
}

// pushTarget returns the target to use for git push/fetch commands for checkpoint branches.
// If a checkpoint URL is configured, returns that; otherwise returns the remote name.
func (ps *pushSettings) pushTarget() string {
	if ps.checkpointURL != "" {
		return ps.checkpointURL
	}
	return ps.remote
}

// hasCheckpointURL returns true if a dedicated checkpoint URL is configured.
func (ps *pushSettings) hasCheckpointURL() bool {
	return ps.checkpointURL != ""
}

// resolvePushSettings loads settings once and returns the resolved push config.
// If a structured checkpoint_remote is configured (e.g., {"provider": "github", "repo": "org/repo"}):
//   - Derives the checkpoint URL from the push remote's protocol (SSH vs HTTPS)
//   - Skips if the push remote owner differs from the checkpoint repo owner (fork detection)
//   - If a checkpoint branch doesn't exist locally, attempts to fetch it from the URL
//
// The push itself handles failures gracefully (doPushRef warns and continues),
// so no reachability check is needed here.
func resolvePushSettings(ctx context.Context, pushRemoteName string) pushSettings {
	s, err := settings.Load(ctx)
	if err != nil {
		return pushSettings{remote: pushRemoteName}
	}

	ps := pushSettings{
		remote:       pushRemoteName,
		pushDisabled: s.IsPushSessionsDisabled(),
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		return ps
	}
	checkpointURL, enabled, err := remote.PushURL(ctx, pushRemoteName)
	if err != nil {
		logging.Warn(ctx, "checkpoint-remote: could not derive URL from push remote",
			slog.String("remote", pushRemoteName),
			slog.String("repo", config.Repo),
			slog.String("error", err.Error()),
		)
		return ps
	}
	if !enabled || checkpointURL == "" {
		return ps
	}

	ps.checkpointURL = checkpointURL

	// If the v1 checkpoint branch doesn't exist locally, try to fetch it from the URL.
	// This is a one-time operation — once the branch exists locally, subsequent pushes
	// skip the fetch entirely. Only fetch the metadata branch; trails are always pushed
	// to the user's push remote, not the checkpoint remote.
	if err := fetchMetadataBranchIfMissing(ctx, checkpointURL); err != nil {
		logging.Warn(ctx, "checkpoint-remote: failed to fetch metadata branch",
			slog.String("error", err.Error()),
		)
	}

	return ps
}

// FetchMetadataBranch fetches the metadata branch from the checkpoint remote URL
// and updates the local branch. Unlike fetchMetadataBranchIfMissing, this always
// fetches regardless of whether the branch exists locally (for resume scenarios
// where the local branch may be stale).
//
// The fetch is unfiltered (NoFilter: true) because resume needs blob content
// (transcripts, metadata JSON) — not just tree objects.
func FetchMetadataBranch(ctx context.Context, remoteURL string) error {
	refs := checkpoint.ResolveCommittedRefs(ctx)
	if !refs.Primary.IsBranch() {
		return fmt.Errorf("primary metadata ref %s is not a branch", refs.Primary)
	}
	branchName := refs.Primary.Short()
	tmpRef := FetchTmpRefPrefix + branchName
	srcRef := refs.Primary.String()

	if err := fetchURLIntoTmpRef(ctx, remoteURL, srcRef, tmpRef, "metadata branch", true); err != nil {
		return err
	}
	if err := PromoteTmpRefSafely(ctx, plumbing.ReferenceName(tmpRef), refs.Primary, branchName); err != nil {
		return err
	}

	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Warn(ctx, "committed-ref mirror skipped after metadata fetch",
			slog.String("error", err.Error()))
		return nil
	}
	defer repo.Close()
	mirrorCommittedMetadataRefBestEffort(ctx, repo, refs)
	return nil
}

// fetchURLIntoTmpRef runs `git fetch <remoteURL> +<srcRef>:<tmpRef>` via the
// checkpoint git wrapper, disabling the terminal prompt so a misconfigured
// credential helper doesn't hang the process. Errors include the redacted URL
// and any captured stderr so operators can diagnose without credentials
// leaking into logs.
//
// When noFilter is true, --filter=blob:none is suppressed even if filtered
// fetches are globally enabled. Use noFilter for operations that need blob
// content (resume, explain) as opposed to sync operations (push recovery)
// that only need tree structure.
func fetchURLIntoTmpRef(ctx context.Context, remoteURL, srcRef, tmpRef, label string, noFilter bool) error {
	fetchCtx, cancel := context.WithTimeout(ctx, checkpointRemoteFetchTimeout)
	defer cancel()

	refSpec := fmt.Sprintf("+%s:%s", srcRef, tmpRef)
	output, fetchErr := remote.Fetch(fetchCtx, remote.FetchOptions{
		Remote:   remoteURL,
		RefSpecs: []string{refSpec},
		NoTags:   true,
		NoFilter: noFilter,
	})
	if fetchErr == nil {
		return nil
	}

	redactedURL := remote.RedactURL(remoteURL)
	msg := strings.TrimSpace(strings.ReplaceAll(string(output), remoteURL, redactedURL))
	if msg != "" {
		return fmt.Errorf("fetch %s from %s failed: %s: %w", label, redactedURL, msg, fetchErr)
	}
	return fmt.Errorf("fetch %s from %s failed: %w", label, redactedURL, fetchErr)
}

// fetchMetadataBranchIfMissing fetches the primary metadata ref from a URL only if it doesn't exist locally.
// This avoids network calls on every push — once the branch exists locally, this is a no-op.
// Fetch failures are silently swallowed (returns nil): the push will handle creating the
// branch on the remote. Only fatal errors (opening repo, creating local branch) are returned.
func fetchMetadataBranchIfMissing(ctx context.Context, remoteURL string) error {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}
	defer repo.Close()

	// Check if branch already exists locally - if so, nothing to do
	refs := checkpoint.ResolveCommittedRefs(ctx)
	if _, err := repo.Reference(refs.Primary, true); err == nil {
		return nil // Branch exists locally, skip fetch
	}

	// Branch doesn't exist locally - try to fetch it from the URL.
	// Fetch failures are not fatal: push will create it on the remote when it succeeds.
	if err := FetchMetadataBranch(ctx, remoteURL); err != nil {
		return nil
	}

	logging.Info(ctx, "checkpoint-remote: fetched metadata branch from URL")
	return nil
}
package strategy

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/exec"
	"strings"
	"sync"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/perf"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// pushRefIfNeeded pushes a ref to the given target if it has unpushed changes.
// The target can be a remote name (e.g., "origin") or a URL for direct push.
// For branch refs, the "has unpushed" optimization consults the remote-tracking
// ref. Non-branch refs and URL targets skip the optimization and let git
// handle the no-op case.
// Does not check any settings — callers are responsible for gating.
func pushRefIfNeeded(ctx context.Context, target string, ref plumbing.ReferenceName) error {
	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Debug(ctx, "push skipped: open repository failed",
			slog.String("ref", ref.String()),
			slog.String("error", err.Error()))
		return nil
	}
	defer repo.Close()

	localRef, err := repo.Reference(ref, true)
	if err != nil {
		// Ref doesn't exist locally — nothing to push.
		return nil
	}

	if ref.IsBranch() && !remote.IsURL(target) && !hasUnpushedBranchRef(repo, target, localRef.Hash(), ref.Short()) {
		return nil
	}

	return doPushRef(ctx, target, ref)
}

// hasUnpushedBranchRef checks if the local branch differs from the remote.
// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
func hasUnpushedBranchRef(repo *git.Repository, remoteName string, localHash plumbing.Hash, branchName string) bool {
	// Check for remote tracking ref: refs/remotes/<remoteName>/<branch>
	remoteRefName := plumbing.NewRemoteReferenceName(remoteName, branchName)
	remoteRef, err := repo.Reference(remoteRefName, true)
	if err != nil {
		// Remote branch doesn't exist yet - we have content to push
		return true
	}

	// If local and remote point to same commit, nothing to sync
	// This is the only case where we skip - any difference needs handling
	return localHash != remoteRef.Hash()
}

func displayPushTarget(target string) string {
	if remote.IsURL(target) {
		return "checkpoint remote"
	}
	return target
}

// checkpointPushBudget is one shared deadline across the initial push,
// fetch+rebase, and retry — per-attempt timeouts can stack to ~3x. var so tests
// can shrink it.
var checkpointPushBudget = 2 * time.Minute

// doPushRef pushes the given ref to the target with fetch+rebase recovery.
// The target can be a remote name or a URL.
func doPushRef(ctx context.Context, target string, ref plumbing.ReferenceName) error {
	ctx, cancel := context.WithTimeout(ctx, checkpointPushBudget)
	defer cancel()

	displayTarget := displayPushTarget(target)
	refLabel := refDisplayName(ref)

	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", refLabel, displayTarget)
	stop := startProgressDots(os.Stderr)

	// Try pushing first
	result, err := tryPushRefCommon(ctx, target, ref)
	if err == nil {
		finishPush(ctx, stop, result, target)
		return nil
	}
	stop("")

	// Protected refs cannot be fixed by syncing and retrying.
	var protectedErr *protectedRefError
	if errors.As(err, &protectedErr) {
		printProtectedRefBlock(os.Stderr, refLabel, target)
		return nil
	}

	// Push failed - likely non-fast-forward. Try to fetch and rebase.
	// Spanned (with the network fetch as a child) so the trace distinguishes
	// "the raw push is slow" from "we keep hitting contention and re-syncing".
	fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", refLabel)
	stop = startProgressDots(os.Stderr)

	frCtx, fetchRebaseSpan := perf.Start(ctx, "fetch_and_rebase")
	syncErr := fetchAndRebaseRefCommon(frCtx, target, ref)
	fetchRebaseSpan.RecordError(syncErr)
	fetchRebaseSpan.End()
	if syncErr != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", refLabel, syncErr)
		printCheckpointRemoteHint(target)
		return nil // Don't fail the main push
	}
	stop(" done")

	// Try pushing again after rebase
	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", refLabel, displayTarget)
	stop = startProgressDots(os.Stderr)

	if result, err := tryPushRefCommon(ctx, target, ref); err != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", refLabel, err)
		printCheckpointRemoteHint(target)
	} else {
		finishPush(ctx, stop, result, target)
	}

	return nil
}

// refDisplayName returns a user-readable name for ref. Branch refs use the
// short name (e.g. "entire/checkpoints/v1"); other refs use the full name.
func refDisplayName(ref plumbing.ReferenceName) string {
	if ref.IsBranch() {
		return ref.Short()
	}
	return ref.String()
}

// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
// Only prints when the target is a URL (not the user's default remote).
func printCheckpointRemoteHint(target string) {
	if !remote.IsURL(target) {
		return
	}
	fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
	fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
}

// settingsHintOnce ensures the settings commit hint prints at most once per process.
var settingsHintOnce sync.Once

// printSettingsCommitHint prints a hint after a successful checkpoint remote push
// when the committed .entire/settings.json does not contain a checkpoint_remote config.
// entire.io discovers the external checkpoint repo by reading the committed project
// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
// (not just in settings.local.json or uncommitted local changes).
// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
// single pre-push invocation.
func printSettingsCommitHint(ctx context.Context, target string) {
	if !remote.IsURL(target) {
		return
	}
	settingsHintOnce.Do(func() {
		if isCheckpointRemoteCommitted(ctx) {
			return
		}
		fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
	})
}

// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
// at HEAD contains a valid checkpoint_remote configuration. This is the true
// discoverability check: entire.io reads from committed project settings, not from
// local overrides or uncommitted changes.
func isCheckpointRemoteCommitted(ctx context.Context) bool {
	cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
	output, err := cmd.Output()
	if err != nil {
		return false // file doesn't exist at HEAD
	}
	// Parse the committed content and check for checkpoint_remote
	committed, err := settings.LoadFromBytes(output)
	if err != nil {
		return false
	}
	return committed.GetCheckpointRemote() != nil
}

// pushResult describes what happened during a push attempt.
type pushResult struct {
	// upToDate is true when the remote already had all commits (nothing transferred).
	upToDate bool
}

// parsePushResult checks git push --porcelain output for ref status flags.
// In porcelain mode, each ref gets a tab-delimited status line:
//
//	<flag>\t<from>:<to>\t<summary>
//
// where flag '=' means the ref was already up-to-date. This is locale-independent,
// unlike the human-readable "Everything up-to-date" message.
func parsePushResult(output string) pushResult {
	for _, line := range strings.Split(output, "\n") {
		if strings.HasPrefix(line, "=\t") {
			return pushResult{upToDate: true}
		}
	}
	return pushResult{upToDate: false}
}

// finishPush stops the progress dots and prints "already up-to-date" or "done"
// depending on the push result. Only prints the settings commit hint when new
// content was actually pushed.
func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
	if result.upToDate {
		stop(" already up-to-date")
	} else {
		stop(" done")
		printSettingsCommitHint(ctx, target)
	}
}

// tryPushRefCommon attempts to push a ref. No timeout of its own —
// runs under doPushRef's shared budget. Branch refs use a bare branch-name
// refSpec so existing remote-tracking works; non-branch refs use a force
// refspec ("+refs/...:refs/...") with no tracking shadow.
func tryPushRefCommon(ctx context.Context, remoteName string, ref plumbing.ReferenceName) (pushResult, error) {
	refSpec := ref.Short()
	if !ref.IsBranch() {
		refSpec = "+" + ref.String() + ":" + ref.String()
	}

	// Span the actual `git push` subprocess: on a slow remote (e.g. a custom
	// git transport) this is typically where pre-push time is spent. Called once
	// per push attempt, so a retry after fetch+rebase shows up as a second
	// git_push step (git_push~1) in the trace. A rejected first push records an
	// error flag, which signals the recovery path was taken.
	_, pushSpan := perf.Start(ctx, "git_push")
	result, err := remote.Push(ctx, remoteName, refSpec)
	pushSpan.RecordError(err)
	pushSpan.End()

	outputStr := result.Output
	if err != nil {
		return pushResult{}, classifyPushFailure(ctx, outputStr, err)
	}

